        const items=mode==='arena'?[...seeds,...deathSeeds]:[food];itemMesh.count=items.length;items.forEach((item,index)=>{const p=toWorld(item),scale=item.big?1.7:1;temp.position.set(p.x,item.big?.74:.42,p.z);temp.scale.setScalar(scale);temp.rotation.set(0,0,0);temp.updateMatrix();itemMesh.setMatrixAt(index,temp.matrix);tempColor.set(item.tech.color);itemMesh.setColorAt(index,tempColor);});itemMesh.instanceMatrix.needsUpdate=true;if(itemMesh.instanceColor)itemMesh.instanceColor.needsUpdate=true;
