    const syncPlatformHud=()=>{const stats=root.querySelector('#platformStats'),collected=level.tokens.filter(token=>token.taken).length;if(stats)stats.innerHTML=`<span>${phaseLabel(phase)}</span><span>❤ ${lives}</span><span>01 ${collected}/${level.tokens.length}</span><span>★ ${score}</span><span>↪ ${Math.round(checkpoint/10)}</span>`;root.querySelectorAll('[data-action="action"]').forEach(button=>{button.disabled=paused;button.textContent='Usar portal';button.setAttribute('aria-label','Usar o portal de dados próximo');});};
    activePause=value=>{paused=value;if(value){keys.clear();interactUntil=0;}else last=performance.now();syncPlatformHud();};
