  function renderGame(){stop();stage()?.classList.remove('has-arcade-canvas','has-drone-fallback');setStatus('Cada jogo possui cinco fases ou cinco etapas. XP acadêmico nunca é concedido por sorte, lucro aleatório ou repetição.');if(state.game==='snake')startSnake();else if(state.game==='hangman')startHangman();else if(state.game==='trio')startTrio();else if(state.game==='trend')startTrend();else if(state.game==='pac')startPac();else if(state.game==='memory')startMemory();else if(state.game==='platform')startPlatform();else startDrone();installPlayfieldChrome();scheduleLayoutRefresh();}
