  function render(){root.innerHTML=`<div class="arcade-shell"><header class="immersive-hero arcade-hero"><div><span class="eyebrow">ARCADE EDUCACIONAL • CINCO FASES • REGRAS TRANSPARENTES</span><h2>Arcade Tech</h2><p>Jogos com progressão real, controles móveis, penalidades coerentes e recompensas protegidas contra repetição e sorte.</p></div><div class="arcade-currency"><span>Créditos <b id="arcadeBits">${state.bits}</b></span><span>Recorde <b id="arcadeBest">0</b></span></div></header><div class="arcade-grid"><nav class="arcade-menu">${Object.entries(GAMES).map(([id,game])=>`<button type="button" data-game="${id}"><span class="game-emoji">${game.emoji}</span><span><strong>${game.name}</strong><small>${game.desc}</small></span></button>`).join('')}</nav><section class="arcade-stage"><header class="arcade-stage-head"><div><span class="eyebrow">JOGO ATUAL</span><h3 id="arcadeGameTitle"></h3><p id="arcadeGameDesc"></p></div><div class="arcade-stage-actions"><button id="pauseGame" class="btn secondary" type="button" aria-pressed="false">Pausar</button><button id="restartGame" class="btn secondary" type="button">Reiniciar</button><button id="toggleImmersive" class="btn primary" type="button" aria-pressed="false">Tela cheia</button></div></header><div id="arcadePlayfield" class="arcade-playfield"></div><div class="arcade-info"><div id="arcadeKnowledge" class="knowledge-card"></div><details class="code-reveal"><summary>Como esta mecânica funciona?</summary><pre id="arcadeCode"></pre><p>Trecho simplificado. Use o Ambiente JavaScript para editar programas completos.</p></details></div><div id="arcadeStatus" class="practice-feedback"></div></section></div></div>`;root.querySelectorAll('[data-game]').forEach(button=>button.onclick=()=>setGame(button.dataset.game));root.querySelector('#restartGame').onclick=renderGame;bindShellControls();setGame(state.game);}
  async function mount(host,context){root=host;ctx=context;const saved=await ctx.storage.get(KEY,DEFAULT)||DEFAULT;state={...DEFAULT,...saved,schemaVersion:5,best:{...DEFAULT.best,...saved.best},plays:{...saved.plays},wins:{...saved.wins}};if(state.game==='runner'||!GAMES[state.game])state.game='snake';if(!['classic','arena','3d','360'].includes(state.snakeMode))state.snakeMode=state.snakeMode==='2d'?'classic':state.snakeMode==='3d'?'3d':'classic';state.controlLayout=state.controlLayout==='move-right'?'move-right':'move-left';state.controlSensitivity=clamp(Number(state.controlSensitivity)||1,.6,1.5);state.controlDeadZone=clamp(Number(state.controlDeadZone)||.18,.08,.35);render();}
